var a=`0160-spaghetti-carbonara`;var n=`world-0160`;var i=`IT`;var s=`southern-europe`;var o=4;var r=24;var g={en:`Spaghetti Carbonara`,ua:`Спагеті карбонара`};var c={en:`A classic dish from Italy, featuring guanciale, spaghetti, chicken egg, pecorino romano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: гуанчале, спагеті, куряче яйце, пекоріно романо. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Cut guanciale into strips and render gently in a dry pan until crisp, keeping the fat.`,ua:`Наріжте гуанчале смужками й повільно витопіть на сухій сковороді до хрусткості; збережіть жир.`,t:[`searing`],m:10,i:[[`guanciale`,170,`g`]]},{en:`Boil spaghetti until just al dente; reserve some hot starchy cooking water.`,ua:`Відваріть спагеті до аль денте; збережіть трохи гарячої крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`spaghetti`,380,`g`],[`water`,1700,`ml`],[`table-salt`,10,`g`]]},{en:`Off the heat, toss hot pasta with guanciale, then fold in egg, Pecorino and black pepper; loosen with reserved water until glossy and creamy. Do not scramble the eggs.`,ua:`Зніміть сковороду з вогню, змішайте пасту з гуанчале, додайте яйця, пекоріно й чорний перець; розбавте водою з-під пасти до кремового соусу, не даючи яйцям згорнутися.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:4,i:[[`chicken-egg`,3,`pcs`],[`pecorino-romano`,110,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var p={slug:a,id:n,country:`IT`,region:s,servings:4,minutes:24,title:g,text:c,steps:l};export{i as country,p as default,n as id,r as minutes,s as region,o as servings,a as slug,l as steps,c as text,g as title};